class StudentPhoto extends StatelessWidget{final Student? student;final double size;const StudentPhoto({super.key,required this.student,required this.size});@override Widget build(BuildContext context){final p=student?.imagePath,net=p!=null&&(p.startsWith('http://')||p.startsWith('https://'));return Container(width:size,height:size,decoration:BoxDecoration(color:blueSoft,borderRadius:BorderRadius.circular(size*.2),border:Border.all(color:const Color(0xFFC9D3DE),width:1.2)),clipBehavior:Clip.antiAlias,child:net?Image.network(p!,fit:BoxFit.cover,errorBuilder:(_,__,___)=>Icon(Icons.person_rounded,color:blue,size:size*.48)):Icon(Icons.person_rounded,color:blue,size:size*.48));}}
class EmptyState extends StatelessWidget{final String title,subtitle;const EmptyState({super.key,required this.title,required this.subtitle});@override Widget build(BuildContext context)=>Center(child:Padding(padding:const EdgeInsets.all(35),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Container(width:68,height:68,decoration:BoxDecoration(color:blueSoft,borderRadius:BorderRadius.circular(22)),child:const Icon(Icons.inbox_outlined,color:blue,size:31)),const SizedBox(height:15),Text(title,style:const TextStyle(fontSize:18,fontWeight:FontWeight.w900,color:textDark)),const SizedBox(height:6),Text(subtitle,textAlign:TextAlign.center,style:const TextStyle(color:muted,fontSize:13))])));}
class AppDropdown extends StatelessWidget{final String value;final List<String> items;final List<String>? labels;final ValueChanged<String?>? onChanged;const AppDropdown({super.key,required this.value,required this.items,this.labels,required this.onChanged});@override Widget build(BuildContext context){final v=items.contains(value)?value:(items.isEmpty?null:items.first);return DropdownButtonFormField<String>(value:v,items:List.generate(items.length,(i)=>DropdownMenuItem<String>(value:items[i],child:Text(labels==null?items[i]:labels![i]))),onChanged:onChanged);}}
class ManageRow extends StatelessWidget{final Widget photo;final String title,subtitle;final VoidCallback? onDelete;const ManageRow({super.key,required this.photo,required this.title,required this.subtitle,this.onDelete});@override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(18),border:Border.all(color:border)),child:Row(children:[photo,const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontWeight:FontWeight.w800,color:textDark)),const SizedBox(height:4),Text(subtitle,style:const TextStyle(fontSize:11,color:muted))])),if(onDelete!=null)IconButton(onPressed:onDelete,icon:const Icon(Icons.delete_outline_rounded,color:red))]));}
